import React from 'react';
import Slider from 'react-slick';
import { Box, Container, Button } from '@mui/material';
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function EventsSlider() {
    const slides = [
        {
            id: 1,
            image: "https://cdn.gcp.techcareer.net/luxoft_hackathon_1112x412_3468c22c84/luxoft_hackathon_1112x412_3468c22c84.png",
            link: "https://www.techcareer.net/hackathon/luxoft-parking-hackathon",
            alt: "Luxoft Parking Hackathon"
        },
        {
            id: 2,
            image: "https://cdn.gcp.techcareer.net/2024_duyurular_1112x412_ccf8c238f3/2024_duyurular_1112x412_ccf8c238f3.png",
            link: "https://survey.alchemer.com/s3/8068418/N240021",
            alt: "TechReport2024 Yazılımcı Anketi"
        },
        // Daha fazla slide ekleyebilirsiniz
    ];

    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 1,
        slidesToScroll: 1,
            autoplay: true,
        autoplaySpeed: 5000,
        arrows: true,
        fade: true,
        responsive: [
            {
                breakpoint: 1024,
                settings: {
                    arrows: false
                }
            }
        ]
    };

    return (
        <Box sx={{ 
            position: 'relative',
            width: '100%',
            overflow: 'hidden',
            backgroundImage: 'url(/src/assets/Carousel.PNG)',
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            backgroundRepeat: 'no-repeat',
            '&::before': {
                content: 'none'
            },
            '&::after': {
                content: 'none'
            },
            '& .slick-dots': {
                bottom: '20px',
                zIndex: 2,
                '& li button:before': {
                    color: '#fff',
                    opacity: 0.5,
                    fontSize: '12px'
                },
                '& li.slick-active button:before': {
                    color: '#fff',
                    opacity: 1
                }
            },
            '& .slick-prev, & .slick-next': {
                zIndex: 2,
                width: '40px',
                height: '40px',
                backgroundImage: 'url(../src/assets/images/call-to-actions/home/Carousel.PNG)',
                borderRadius: '50%',
                transition: 'all 0.3s ease',
                transform: 'translateY(-50%)',
                '&:before': {
                    fontSize: '24px',
                    opacity: 0.7,
                    lineHeight: '40px',
                    color: '#000',
                },
                '&:hover': {
                    backgroundColor: 'rgba(255, 255, 255, 0.8)',
                    '&:before': {
                        opacity: 1
                    }
                }
            },
            '& .slick-prev': {
                left: { xs: '20px', md: '40px' },
            },
            '& .slick-next': {
                right: { xs: '20px', md: '40px' },
            }
        }}>
            {/* Süsleme öğeleri */}
            <Box
                sx={{
                    position: 'absolute',
                    top: '20px',
                    left: '20px',
                    zIndex: 1,
                    '& img': {
                        width: '50px',
                        height: '50px'
                    }
                }}
            >
                <img 
                    src="/assets/images/call-to-actions/home/shape-dots.svg" 
                    alt="" 
                    draggable="false"
                />
            </Box>
            <Box
                sx={{
                    position: 'absolute',
                    top: '20px',
                    right: '20px',
                    zIndex: 1,
                    '& img': {
                        width: '142px',
                        height: '142px'
                    }
                }}
            >
                <img 
                    src="/assets/images/call-to-actions/home/kesik-yan-cizgi.svg" 
                    alt="" 
                    draggable="false"
                />
            </Box>

            {/* Ana Slider */}
            <Container 
                maxWidth="lg" 
                sx={{ 
                    py: 4,
                    position: 'relative',
                    zIndex: 1,
                    px: { xs: 1, md: 3 },
                }}
            >
                <Slider {...settings}>
                    {slides.map((slide) => (
                        <Box key={slide.id}>
                            <Button
                                component="a"
                                href={slide.link}
                                sx={{
                                    p: 2,
                                    width: '100%',
                                    textAlign: 'center',
                                    backgroundColor: '#fff',
                                    borderRadius: '12px',
                                    '&:hover': {
                                        backgroundColor: '#fff'
                                    }
                                }}
                            >
                                <img
                                    src={slide.image}
                                    alt={slide.alt}
                                    style={{
                                        width: '100%',
                                        height: 'auto',
                                        maxHeight: '412px',
                                        objectFit: 'cover',
                                        borderRadius: '8px',
                                        boxShadow: '0 4px 20px rgba(0, 0, 0, 0.1)'
                                    }}
                                    draggable="false"
                                />
                            </Button>
                        </Box>
                    ))}
                </Slider>
            </Container>
        </Box>
    );
}

export default EventsSlider;
